package com.example.domain.model.i18n

internal object DuaHi3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("तेरी रहमत का उम्मीदवार हूँ", "ऐ अल्लाह! मैं तेरी रहमत का उम्मीदवार हूँ, तो मुझे पलक झपकने के बराबर भी मेरे नफ़्स के हवाले न कर, और मेरे सारे काम दुरुस्त फ़रमा दे। तेरे सिवा कोई माबूद नहीं।", "परेशान हाल की दुआ (दअवातुल-मकरूब)।", "नबी ﷺ ने इसे परेशान हाल की दुआ फ़रमाया।"),
        "dua_against_enemy_ahzab" to DuaText("दुश्मन के लश्करों के ख़िलाफ़", "ऐ अल्लाह, किताब उतारने वाले, जल्द हिसाब लेने वाले! लश्करों को शिकस्त दे। ऐ अल्लाह! उन्हें शिकस्त दे और उनके क़दम हिला दे।", "दुश्मन के मुक़ाबले में — ग़ज़वा-ए-अहज़ाब की दुआ।", "नबी ﷺ की दुश्मन के ख़िलाफ़ दुआ।"),
        "dua_anta_adudi" to DuaText("तू ही मेरा सहारा है", "ऐ अल्लाह! तू ही मेरा बाज़ू और मददगार है। तेरे ही ज़रिए मैं तदबीर करता हूँ, तेरे ही ज़रिए हमला करता हूँ और तेरे ही ज़रिए लड़ता हूँ।", "मुक़ाबले या बड़े चैलेंज से पहले।", "नबी ﷺ जंग के वक़्त यह फ़रमाते।"),
        "dua_ikfinihim" to DuaText("उनके मुक़ाबले में मुझे काफ़ी हो जा", "ऐ अल्लाह! जैसे तू चाहे उनके मुक़ाबले में मेरे लिए काफ़ी हो जा।", "ज़ालिमों के शर से — असहाबुल-उख़दूद के लड़के की दुआ।", "अल्लाह ने लड़के को ज़ालिमों से बचा लिया।"),
        "dua_qadarullah" to DuaText("जब कुछ बुरा हो जाए", "अल्लाह की तक़दीर है, और उसने जो चाहा किया।", "कोई नागवार बात हो जाए तो 'काश' कहने के बजाय।", "'काश' शैतान का दरवाज़ा खोलता है।"),
        "dua_ala_kulli_hal" to DuaText("हर हाल में तारीफ़", "हर हाल में सारी तारीफ़ अल्लाह के लिए है।", "कोई नापसंद बात पेश आए तो।", "नबी ﷺ नापसंद चीज़ पर यह फ़रमाते।"),
        "dua_dogs_barking" to DuaText("रात को कुत्तों का भौंकना सुनकर", "मैं अल्लाह की पनाह माँगता हूँ मरदूद शैतान से।", "रात को कुत्तों के भौंकने या गधे के रेंकने पर।", "वे ऐसी चीज़ें देखते हैं जो तुम नहीं देखते।"),
        "dua_leaving_home_adilla" to DuaText("गुमराही से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ इससे कि मैं गुमराह हूँ या गुमराह किया जाऊँ, फिसलूँ या फिसला दिया जाऊँ, ज़ुल्म करूँ या मुझ पर ज़ुल्म हो, जहालत करूँ या मेरे साथ जहालत की जाए।", "घर से निकलते वक़्त — हज़रत उम्मे सलमा (रज़ि.) की रिवायत।", "नबी ﷺ जब भी घर से निकलते तो यह पढ़ते।"),
        "dua_ascending_descending" to DuaText("चढ़ाई और उतराई", "अल्लाह सबसे बड़ा है (चढ़ाई पर)। — अल्लाह पाक है (उतराई पर)।", "सफ़र में चढ़ाई पर 'अल्लाहु अकबर', उतराई पर 'सुब्हानल्लाह'।", "सहाबा (रज़ि.) का सफ़र में मामूल।"),
        "dua_traveller_sahar" to DuaText("सुबह से पहले मुसाफ़िर की दुआ", "सुनने वाले ने अल्लाह की तारीफ़ और हम पर उसके अच्छे इनामात को (दूसरों तक) सुना दिया। ऐ हमारे रब! हमारा साथी बन और हम पर फ़ज़्ल फ़रमा — मैं आग से अल्लाह की पनाह माँगते हुए (यह कहता हूँ)।", "सफ़र में सहरी के वक़्त।", "नबी ﷺ सफ़र में सहरी के वक़्त यह फ़रमाते।"),
        "dua_zawwadakallah" to DuaText("मुसाफ़िर को: अल्लाह तक़वा का तोशा दे", "अल्लाह तुम्हें तक़वा का ज़ाद-ए-राह दे, तुम्हारे गुनाह माफ़ करे और तुम जहाँ भी हो तुम्हारे लिए भलाई आसान करे।", "मुसाफ़िर को रुख़्सत करते वक़्त।", "नबी ﷺ ने सफ़र पर जाने वाले को यह दुआ दी।"),
        "dua_traveller_to_resident" to DuaText("मुसाफ़िर की घर वालों के लिए दुआ", "मैं तुम्हें उस अल्लाह के सुपुर्द करता हूँ जिसके पास रखी अमानतें ज़ाया नहीं होतीं।", "सफ़र पर जाने वाला घर वालों को रुख़्सत करते वक़्त।", "घर वालों की हिफ़ाज़त अल्लाह के सुपुर्द।"),
        "dua_entering_village" to DuaText("किसी बस्ती या शहर में दाख़िल होना", "ऐ अल्लाह, सात आसमानों और जिन पर उनका साया है उनके रब, सात ज़मीनों और जो उन्होंने उठाया है उनके रब, शैतानों और जिन्हें उन्होंने गुमराह किया उनके रब, हवाओं और जो उन्होंने उड़ाया उनके रब! हम तुझसे इस बस्ती की और इसके रहने वालों की भलाई माँगते हैं, और इसके, इसके लोगों के और जो इसमें है उसके शर से तेरी पनाह माँगते हैं।", "किसी बस्ती/शहर में दाख़िल होने से पहले।", "नबी ﷺ जिस बस्ती में दाख़िल होना चाहते यह पढ़ते।"),
        "dua_vehicle_stumbles" to DuaText("सवारी फिसले तो", "अल्लाह के नाम से।", "सवारी फिसले या ठोकर लगे तो 'शैतान बर्बाद हो' कहने के बजाय।", "बिस्मिल्लाह कहने से शैतान मक्खी जैसा छोटा हो जाता है।"),
        "dua_ajz_kasal_haram" to DuaText("लाचारी और बुढ़ापे से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ लाचारी और सुस्ती से, बुज़दिली और बुढ़ापे से, ज़िंदगी और मौत के फ़ितने से, और क़ब्र के अज़ाब से।", "रोज़ाना पनाह की जामे दुआ।", "नबी ﷺ की कसरत से माँगी जाने वाली दुआ।"),
        "dua_sharri_ma_amiltu" to DuaText("अपने आमाल के शर से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ उस अमल के शर से जो मैंने किया, और उसके शर से जो मैंने नहीं किया।", "हज़रत आइशा (रज़ि.) के मुताबिक़ नबी ﷺ की दुआ।", "किए और न किए दोनों के अंजाम से हिफ़ाज़त।"),
        "dua_jahdil_bala" to DuaText("सख़्त आज़माइश से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ सख़्त आज़माइश से, बदबख़्ती के आ पकड़ने से, बुरे फ़ैसले से और दुश्मनों के हँसने से।", "सख़्त आज़माइश और दुश्मनों की ख़ुशी से पनाह।", "नबी ﷺ इन चार चीज़ों से पनाह माँगते थे।"),
        "dua_fitnat_ghina_faqr" to DuaText("मालदारी और ग़ुरबत के फ़ितने से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ सुस्ती और बुढ़ापे से, गुनाह और क़र्ज़ से, क़ब्र के फ़ितने और अज़ाब से, आग के फ़ितने और अज़ाब से, मालदारी के फ़ितने के शर से, और ग़ुरबत के फ़ितने से।", "क़ब्र, जहन्नम, मालदारी और ग़ुरबत के फ़ितनों से पनाह (दुआ का हिस्सा)।", "नबी ﷺ की जामे पनाह की दुआ।"),
        "dua_kufr_faqr" to DuaText("कुफ़्र और फ़क़्र से पनाह", "ऐ अल्लाह! मैं कुफ़्र और फ़क़्र से तेरी पनाह माँगता हूँ, और क़ब्र के अज़ाब से तेरी पनाह माँगता हूँ। तेरे सिवा कोई माबूद नहीं।", "सुबह-शाम तीन बार।", "हज़रत अबू बकरा (रज़ि.) ने नबी ﷺ को यह पढ़ते सुना।"),
        "dua_sharri_sami" to DuaText("अपने आज़ा के शर से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ अपने कानों के शर से, अपनी आँखों के शर से, अपनी ज़बान के शर से, अपने दिल के शर से और अपनी शहवत के शर से।", "हज़रत शकल बिन हुमैद (रज़ि.) को सिखाई गई।", "आज़ा और नफ़्स को गुनाह से बचाने की दुआ।"),
        "dua_hadm_gharaq" to DuaText("अचानक मौत और हादसों से पनाह", "ऐ अल्लाह! मैं तेरी पनाह माँगता हूँ (मकान) गिरने से, ऊँचाई से गिरने से, डूबने, जलने और बुढ़ापे से, मौत के वक़्त शैतान के बहकाने से, तेरी राह में पीठ फेरकर मरने से, और (ज़हरीले जानवर के) डसने से मरने से।", "हादसों और बुरी मौत से पनाह।", "नबी ﷺ की पनाह की दुआ।"),
        "dua_ju_khiyanah" to DuaText("भूख और ख़यानत से पनाह", "ऐ अल्लाह! मैं भूख से तेरी पनाह माँगता हूँ क्योंकि वह बुरा साथी है, और ख़यानत से तेरी पनाह माँगता हूँ क्योंकि वह बुरा राज़दार है।", "भूख और ख़यानत से पनाह।", "नबी ﷺ की पनाह की दुआ।"),
        "dua_huda_tuqa" to DuaText("हिदायत, तक़वा, पाकदामनी और बेनियाज़ी", "ऐ अल्लाह! मैं तुझसे हिदायत, तक़वा, पाकदामनी और बेनियाज़ी माँगता हूँ।", "नबी ﷺ की मुख़्तसर जामे दुआ।", "दीन और दुनिया की चार बुनियादी नेमतें।"),
        "dua_aslih_li_dini" to DuaText("मेरा दीन, दुनिया और आख़िरत दुरुस्त कर", "ऐ अल्लाह! मेरा दीन दुरुस्त कर दे जो मेरे हर काम की हिफ़ाज़त है, मेरी दुनिया दुरुस्त कर दे जिसमें मेरी रोज़ी है, मेरी आख़िरत दुरुस्त कर दे जहाँ मुझे लौटना है। ज़िंदगी को मेरे लिए हर भलाई में इज़ाफ़ा बना, और मौत को हर बुराई से राहत बना दे।", "दीन, दुनिया और आख़िरत — तीनों की इस्लाह।", "नबी ﷺ की जामे दुआ।"),
        "dua_musarrifal_qulub" to DuaText("हमारे दिल अपनी इताअत पर फेर दे", "ऐ अल्लाह, दिलों को फेरने वाले! हमारे दिलों को अपनी इताअत की तरफ़ फेर दे।", "दिल को इताअत पर जमाने की दुआ।", "तमाम इंसानों के दिल रहमान की दो उँगलियों के बीच हैं।"),
        "dua_jannah_nar" to DuaText("जन्नत माँगना, आग से पनाह", "ऐ अल्लाह! मैं तुझसे जन्नत माँगता हूँ और आग से तेरी पनाह माँगता हूँ।", "तशह्हुद के बाद या हर वक़्त।", "नबी ﷺ ने फ़रमाया: हम भी इसी के इर्द-गिर्द दुआ करते हैं।"),
        "dua_khayri_kullih" to DuaText("हर भलाई, अभी और बाद में", "ऐ अल्लाह! मैं तुझसे हर भलाई माँगता हूँ — जल्दी वाली और देर वाली, जो मैं जानता हूँ और जो नहीं जानता — और हर बुराई से तेरी पनाह माँगता हूँ — जल्दी वाली और देर वाली, जो मैं जानता हूँ और जो नहीं जानता। ऐ अल्लाह! मैं तुझसे जन्नत और उस क़ौल और अमल का सवाल करता हूँ जो उसके क़रीब करे, और आग से और उस क़ौल और अमल से पनाह माँगता हूँ जो उसके क़रीब करे।", "नबी ﷺ ने हज़रत आइशा (रज़ि.) को यह जामे दुआ सिखाई (दुआ का हिस्सा)।", "हर ख़ैर को समेटने वाली दुआ।"),
        "dua_ihdini_saddidni" to DuaText("मुझे हिदायत दे और सीधा रख", "ऐ अल्लाह! मुझे हिदायत दे और मुझे सीधा रख।", "नबी ﷺ ने हज़रत अली (रज़ि.) को सिखाई।", "हिदायत को रास्ते की हिदायत से और सदाद को तीर के सीधेपन से याद करो।"),
        "dua_hubbaka" to DuaText("अल्लाह की मुहब्बत माँगना", "ऐ अल्लाह! मैं तुझसे तेरी मुहब्बत माँगता हूँ, और उसकी मुहब्बत जो तुझसे मुहब्बत करे, और ऐसा अमल जो मुझे तेरी मुहब्बत तक पहुँचा दे। ऐ अल्लाह! अपनी मुहब्बत को मेरी जान, मेरे घर वालों और ठंडे पानी से भी ज़्यादा मुझे महबूब बना दे।", "हज़रत दाऊद (अ.) की दुआ जो नबी ﷺ ने बयान फ़रमाई।", "अल्लाह की मुहब्बत सबसे बड़ी दौलत।"),
        "dua_filal_khayrat" to DuaText("नेकियाँ करना और बुराइयाँ छोड़ना", "ऐ अल्लाह! मैं तुझसे नेकियाँ करने, बुराइयाँ छोड़ने और मिस्कीनों से मुहब्बत का सवाल करता हूँ, और यह कि तू मुझे बख़्श दे और मुझ पर रहम फ़रमा। और जब तू किसी क़ौम को फ़ितने में डालना चाहे तो मुझे फ़ितने से बचाकर मौत दे। मैं तुझसे तेरी मुहब्बत, तुझसे मुहब्बत करने वालों की मुहब्बत, और उस अमल की मुहब्बत माँगता हूँ जो तेरी मुहब्बत के क़रीब करे।", "ख़्वाब में अल्लाह ने नबी ﷺ को यह दुआ सिखाई।", "नबी ﷺ ने फ़रमाया: यह हक़ है, इसे सीखो और सिखाओ।"),
        "dua_bi_ilmikal_ghayb" to DuaText("जब तक ज़िंदगी बेहतर हो ज़िंदा रख", "ऐ अल्लाह! तेरे इल्म-ए-ग़ैब और मख़लूक़ पर तेरी क़ुदरत के वास्ते से — जब तक तेरे इल्म में ज़िंदगी मेरे लिए बेहतर हो मुझे ज़िंदा रख, और जब मौत बेहतर हो तो मौत दे। ऐ अल्लाह! मैं छुपे और खुले में तेरा ख़ौफ़, ख़ुशी और ग़ुस्से में हक़ बात, और ग़ुरबत और मालदारी में मियानारवी माँगता हूँ।", "हज़रत अम्मार बिन यासिर (रज़ि.) की नमाज़ की दुआ (शुरुआती हिस्सा)।", "नबी ﷺ नमाज़ में यह दुआ फ़रमाते थे।"),
        "dua_ism_azam_mannan" to DuaText("इस्म-ए-आज़म: अल-मन्नान", "ऐ अल्लाह! मैं तुझसे सवाल करता हूँ इस वास्ते से कि सारी तारीफ़ तेरे लिए है, तेरे सिवा कोई माबूद नहीं, तू बहुत एहसान करने वाला, आसमानों और ज़मीन को बेमिसाल बनाने वाला है। ऐ जलाल और इकराम वाले, ऐ ज़िंदा, ऐ क़ायम रखने वाले!", "नबी ﷺ ने फ़रमाया इस शख़्स ने इस्म-ए-आज़म के साथ दुआ की।", "इस नाम से दुआ की जाए तो क़बूल होती है।"),
        "dua_ism_azam_ahad_samad" to DuaText("इस्म-ए-आज़म: अल-अहद अस-समद", "ऐ अल्लाह! मैं तुझसे सवाल करता हूँ इस वास्ते से कि मैं गवाही देता हूँ कि तू ही अल्लाह है, तेरे सिवा कोई माबूद नहीं, अकेला, बेनियाज़, जिसने न किसी को जना न वह जना गया, और न कोई उसका हमसर है।", "नबी ﷺ ने फ़रमाया इसने अल्लाह से उसके इस्म-ए-आज़म के साथ सवाल किया।", "जब इसके ज़रिए माँगा जाए तो अता होता है, और दुआ की जाए तो क़बूल होती है।"),
        "dua_thabbitni_hadiyan" to DuaText("मुझे साबित-क़दम, हिदायत याफ़्ता और हादी बना", "ऐ अल्लाह! मुझे साबित-क़दम रख और मुझे हिदायत देने वाला और हिदायत याफ़्ता बना।", "नबी ﷺ ने हज़रत जरीर (रज़ि.) के लिए यह दुआ की (अपने लिए 'सब्बितनी' कहें)।", "असल दुआ हज़रत जरीर (रज़ि.) के लिए 'सब्बित्हु' के अल्फ़ाज़ से है।"),
        "dua_rabbighfir_tub_alayya" to DuaText("मुझे बख़्श दे और मेरी तौबा क़बूल कर", "ऐ मेरे रब! मुझे बख़्श दे और मेरी तौबा क़बूल फ़रमा, बेशक तू ही तौबा क़बूल करने वाला, रहम करने वाला है।", "एक मजलिस में सौ बार — नबी ﷺ का मामूल।", "सहाबा ने एक मजलिस में नबी ﷺ से सौ बार यह गिनकर सुना।"),
        "dua_rafiq_ala" to DuaText("क़रीब-उल-मौत शख़्स की दुआ", "ऐ अल्लाह! मुझे बख़्श दे, मुझ पर रहम फ़रमा और मुझे रफ़ीक़-ए-आला से मिला दे।", "नबी ﷺ की आख़िरी दुआ — मरीज़ अपने लिए।", "नबी ﷺ ने विसाल के वक़्त यह दुआ फ़रमाई।"),
        "dua_la_bas_tahur" to DuaText("मरीज़ को तसल्ली: पाकीज़गी", "कोई हर्ज नहीं, इन शा अल्लाह (यह बीमारी गुनाहों से) पाक करने वाली है।", "मरीज़ की इयादत में तसल्ली के लिए।", "नबी ﷺ मरीज़ के पास जाते तो यह फ़रमाते।"),
        "dua_talqeen" to DuaText("क़रीब-उल-मौत के लिए तलक़ीन", "अल्लाह के सिवा कोई माबूद नहीं।", "क़रीब-उल-मौत शख़्स के पास कलिमा पढ़ें (उससे ज़बरदस्ती न कहें)।", "जिसका आख़िरी कलाम 'ला इलाहा इल्लल्लाह' हो वह जन्नत में दाख़िल होगा (अबू दाऊद 3116)।"),
        "dua_ahyini_ma_kanat" to DuaText("मौत की तमन्ना के बजाय", "ऐ अल्लाह! जब तक ज़िंदगी मेरे लिए बेहतर हो मुझे ज़िंदा रख, और जब मौत मेरे लिए बेहतर हो तो मुझे मौत दे।", "तकलीफ़ में मौत की तमन्ना के बजाय।", "नबी ﷺ ने मौत की तमन्ना से मना फ़रमाकर यह सिखाया।"),
        "dua_for_one_i_cursed" to DuaText("जिसे बातों से तकलीफ़ दी उसके लिए", "ऐ अल्लाह! जिस मोमिन को भी मैंने बुरा-भला कहा हो, उसे क़यामत के दिन उसके लिए तेरे क़ुर्ब का ज़रिया बना दे।", "ग़ुस्से में किसी को बुरा-भला कह दिया हो तो उसके लिए।", "नबी ﷺ की दुआ।"),
        "dua_praising_someone" to DuaText("किसी की तारीफ़ करते वक़्त", "मैं फ़ुलाँ को ऐसा समझता हूँ, और अल्लाह ही उसका हिसाब लेने वाला है, और मैं अल्लाह के मुक़ाबले में किसी की पाकीज़गी बयान नहीं करता।", "किसी की तारीफ़ करनी हो तो मुबालग़े के बजाय।", "नबी ﷺ ने तारीफ़ का यह अदब सिखाया।"),
        "dua_being_praised" to DuaText("जब आपकी तारीफ़ हो", "ऐ अल्लाह! जो यह कह रहे हैं उस पर मेरी पकड़ न फ़रमा, और मेरे वह गुनाह माफ़ फ़रमा जो यह नहीं जानते।", "अपनी तारीफ़ सुनकर — एक सहाबी (रज़ि.) का अमल।", "तारीफ़ पर तकब्बुर से बचने का तरीक़ा।"),
        "dua_non_muslim_sneezes" to DuaText("जब ग़ैर-मुस्लिम छींके", "अल्लाह तुम्हें हिदायत दे और तुम्हारा हाल दुरुस्त करे।", "ग़ैर-मुस्लिम छींककर 'अल्हम्दुलिल्लाह' कहे तो।", "यहूद नबी ﷺ के पास छींकते थे कि 'यरहमुकल्लाह' कहें, तो आप यह फ़रमाते।"),
        "dua_reply_ahl_kitab_salam" to DuaText("अहल-ए-किताब के सलाम का जवाब", "और तुम पर भी।", "अहल-ए-किताब सलाम करें तो।", "नबी ﷺ का हुक्म।"),
        "dua_fasting_invited" to DuaText("रोज़े में दावत मिले तो", "मैं रोज़े से हूँ।", "रोज़े की हालत में दावत मिले या कोई झगड़ा करे।", "रोज़ेदार दावत क़बूल करे तो मेज़बान के लिए दुआ करे।"),
        "dua_for_who_gave_drink" to DuaText("जिसने खिलाया-पिलाया उसके लिए", "ऐ अल्लाह! जिसने मुझे खिलाया उसे खिला, और जिसने मुझे पिलाया उसे पिला।", "जो खिलाए-पिलाए उसके लिए।", "नबी ﷺ ने हज़रत मिक़दाद (रज़ि.) के लिए यह दुआ फ़रमाई।"),
        "dua_eid_greeting" to DuaText("ईद की मुबारकबाद", "अल्लाह हमसे और तुमसे (आमाल) क़बूल फ़रमाए।", "ईद के दिन एक-दूसरे को — सहाबा-ए-किराम (रज़ि.) का मामूल।", "सहाबा ईद पर मिलकर यह कहते थे।"),
        "dua_wedding_night" to DuaText("निकाह के बाद दुल्हन के लिए", "ऐ अल्लाह! मैं तुझसे इसकी भलाई और उस फ़ितरत की भलाई माँगता हूँ जिस पर तूने इसे पैदा किया, और इसके शर और उस फ़ितरत के शर से तेरी पनाह माँगता हूँ।", "निकाह के बाद बीवी की पेशानी पर हाथ रखकर।", "नबी ﷺ की तालीम — निकाह में बरकत।"),
        "dua_istisqa_ibadak" to DuaText("अपने बंदों और जानवरों को सैराब कर", "ऐ अल्लाह! अपने बंदों और जानवरों को सैराब कर, अपनी रहमत फैला दे और अपनी मुर्दा ज़मीन को ज़िंदा कर दे।", "बारिश की तलब (इस्तिस्क़ा)।", "नबी ﷺ बारिश के लिए यह दुआ फ़रमाते।"),
        "dua_seeing_clouds" to DuaText("काले बादल देखकर", "ऐ अल्लाह! मैं इसके शर से तेरी पनाह माँगता हूँ।", "आसमान पर घटा या बादल देखकर; बारिश हो तो 'अल्लाहुम्मा सय्यिबन नाफ़िआ'।", "नबी ﷺ बादल देखकर काम छोड़ देते और यह दुआ करते।"),
        "dua_jamarat" to DuaText("जमरात की रमी", "अल्लाह सबसे बड़ा है।", "हर कंकरी मारते वक़्त।", "नबी ﷺ हर कंकरी के साथ तकबीर कहते, फिर पहले और दूसरे जमरे के बाद क़िब्ला-रुख़ होकर लंबी दुआ करते।"),
        "dua_rabbi_ainni" to DuaText("ऐ मेरे रब, मेरी मदद कर, मेरे ख़िलाफ़ नहीं", "ऐ मेरे रब! मेरी मदद कर और मेरे ख़िलाफ़ मदद न कर, मुझे ग़लबा दे और मुझ पर ग़लबा न दे, मेरे हक़ में तदबीर कर और मेरे ख़िलाफ़ तदबीर न कर, मुझे हिदायत दे और हिदायत को मेरे लिए आसान कर, और जो मुझ पर ज़ुल्म करे उसके ख़िलाफ़ मेरी मदद कर।", "नबी ﷺ की जामे दुआ (शुरुआती हिस्सा)।", "दुनिया और दीन की हर मदद को जमा करने वाली दुआ।"),
        "dua_ati_nafsi_taqwaha" to DuaText("मेरे नफ़्स को उसका तक़वा दे", "ऐ अल्लाह! मेरे नफ़्स को उसका तक़वा अता फ़रमा और उसे पाक कर दे, तू ही उसे सबसे बेहतर पाक करने वाला है, तू ही उसका कारसाज़ और मालिक है।", "नफ़्स की इस्लाह और तज़किया के लिए।", "नबी ﷺ यह दुआ फ़रमाया करते थे।"),
        "dua_iqsim_lana_khashyatik" to DuaText("हमें अपना ऐसा ख़ौफ़ अता कर", "ऐ अल्लाह! हमें अपना इतना ख़ौफ़ अता कर जो हमारे और तेरी नाफ़रमानी के बीच हायल हो जाए, अपनी इतनी इताअत जो हमें तेरी जन्नत तक पहुँचा दे, और इतना यक़ीन जिससे दुनिया की मुसीबतें हम पर आसान हो जाएँ। जब तक हमें ज़िंदा रखे हमारे कानों, आँखों और क़ुव्वत से हमें फ़ायदा पहुँचा और इसे हमारा वारिस बना। हमारा बदला उससे ले जो हम पर ज़ुल्म करे, दुश्मनों के ख़िलाफ़ हमारी मदद कर, हमारी मुसीबत हमारे दीन में न डाल, दुनिया को हमारा सबसे बड़ा ग़म और हमारे इल्म की इंतिहा न बना, और हम पर ऐसे शख़्स को मुसल्लत न कर जो हम पर रहम न करे।", "मजलिस से उठते वक़्त — नबी ﷺ अक्सर यह दुआ किए बिना न उठते।", "दीन, दुनिया और आख़िरत की भलाइयों की जामे दुआ।"),
        "dua_infani_bima_allamtani" to DuaText("जो सिखाया उससे फ़ायदा दे", "ऐ अल्लाह! जो तूने मुझे सिखाया उससे मुझे फ़ायदा दे, मुझे वह सिखा जो मुझे फ़ायदा दे, और मेरे इल्म में इज़ाफ़ा फ़रमा।", "इल्म हासिल करते वक़्त या पढ़ाई से पहले।", "नफ़ा देने वाले इल्म और उस पर अमल की दुआ।"),
        "dua_jar_su" to DuaText("बुरे पड़ोसी से पनाह", "ऐ अल्लाह! मैं मुस्तक़िल रहने की जगह के बुरे पड़ोसी से तेरी पनाह माँगता हूँ, क्योंकि सफ़र का पड़ोसी तो बदल जाता है।", "बुरे पड़ोसी से हिफ़ाज़त के लिए।", "नबी ﷺ ने इससे पनाह माँगने का हुक्म दिया।"),
        "dua_ishfi_abdak" to DuaText("मरीज़ की शिफ़ा के लिए", "ऐ अल्लाह! अपने बंदे को शिफ़ा दे ताकि वह तेरे लिए दुश्मन का मुक़ाबला करे या तेरे लिए नमाज़ की तरफ़ चलकर जाए।", "मरीज़ की इयादत के वक़्त उसके लिए।", "नबी ﷺ ने मरीज़ के लिए यह कहना सिखाया।"),
        "dua_la_mania" to DuaText("जो तू दे उसे कोई रोक नहीं सकता", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं, उसी की बादशाहत है और उसी की तारीफ़ है और वह हर चीज़ पर क़ादिर है। ऐ अल्लाह! जो तू दे उसे कोई रोकने वाला नहीं और जो तू रोके उसे कोई देने वाला नहीं, और किसी मालदार को उसकी मालदारी तेरे मुक़ाबले में फ़ायदा नहीं देती।", "फ़र्ज़ नमाज़ के सलाम के बाद।", "नबी ﷺ हर फ़र्ज़ नमाज़ के बाद यह फ़रमाते।"),
        "dua_slaughtering" to DuaText("जानवर ज़बह करते वक़्त", "अल्लाह के नाम से, और अल्लाह सबसे बड़ा है।", "क़ुर्बानी या ज़बह करते वक़्त।", "नबी ﷺ ने क़ुर्बानी के वक़्त बिस्मिल्लाह और तकबीर कही।"),
        "dua_undressing" to DuaText("कपड़े उतारते वक़्त", "अल्लाह के नाम से।", "कपड़े उतारते वक़्त (ग़ुस्ल या कपड़े बदलते वक़्त)।", "जिन्नात की नज़र और इंसान के सतर के बीच पर्दा बन जाता है।"),
        "dua_ilbas_jadidan" to DuaText("किसी को नए कपड़ों में देखकर", "नया पहनो, क़ाबिल-ए-तारीफ़ ज़िंदगी गुज़ारो और शहीद होकर मरो।", "किसी मुस्लिम भाई को नए कपड़े पहने देखकर।", "नबी ﷺ ने हज़रत उमर (रज़ि.) को नए कपड़ों में देखकर यह दुआ दी।"),
        "dua_hajj_la_riya" to DuaText("दिखावे से पाक हज", "ऐ अल्लाह! ऐसा हज जिसमें न दिखावा हो न शोहरत-तलबी।", "हज की नीयत के वक़्त इख़लास के लिए।", "नबी ﷺ ने हज के वक़्त यह दुआ फ़रमाई।"),
        "dua_q_muslimayni_laka" to DuaText("हमें फ़रमाँबरदार बना (इब्राहीम और इस्माईल अ.)", "ऐ हमारे रब! हम दोनों को अपना फ़रमाँबरदार बना और हमारी औलाद में से भी एक उम्मत को अपना फ़रमाँबरदार बना, हमें हमारी इबादत के तरीक़े दिखा और हमारी तौबा क़बूल फ़रमा, बेशक तू ही बहुत तौबा क़बूल करने वाला, निहायत रहम वाला है।", "अपने और अपनी औलाद के लिए फ़रमाँबरदारी की दुआ।", "काबा की तामीर के वक़्त की दुआ।"),
        "dua_q_iftah_baynana" to DuaText("हमारे बीच फ़ैसला कर (शुऐब अ.)", "ऐ हमारे रब! हमारे और हमारी क़ौम के बीच हक़ के साथ फ़ैसला कर दे, और तू सबसे बेहतर फ़ैसला करने वाला है।", "हक़ और बातिल के बीच फ़ैसले के लिए।", "हज़रत शुऐब (अ.) की दुआ जब क़ौम ने इनकार किया।"),
        "dua_q_la_akuna_zahiran" to DuaText("मुजरिमों का मददगार कभी नहीं (मूसा अ.)", "ऐ मेरे रब! जैसा तूने मुझ पर इनाम किया, मैं कभी मुजरिमों का मददगार नहीं बनूँगा।", "अल्लाह की नेमतों का शुक्र और गुनहगारों की मदद से बचने का अहद।", "तौबा के बाद हज़रत मूसा (अ.) का अहद।"),
        "dua_q_nuh_unsurni" to DuaText("मेरी मदद कर, उन्होंने मुझे झुठलाया (नूह अ.)", "ऐ मेरे रब! मेरी मदद फ़रमा क्योंकि उन्होंने मुझे झुठला दिया।", "जब लोग झुठलाएँ और हक़ को न मानें।", "हज़रत नूह (अ.) की दुआ जो क़बूल हुई।"),
        "dua_q_ihkum_bil_haqq" to DuaText("ऐ मेरे रब, हक़ के साथ फ़ैसला कर", "ऐ मेरे रब! हक़ के साथ फ़ैसला फ़रमा। और हमारा रब रहमान है, जिससे उन बातों पर मदद माँगी जाती है जो तुम बनाते हो।", "झूठी बातों और इल्ज़ामात के मुक़ाबले में।", "नबी ﷺ को सिखाई गई दुआ।"),
        "dua_ghalabatid_dayn" to DuaText("भारी क़र्ज़ और दुश्मनों से पनाह", "ऐ अल्लाह! मैं क़र्ज़ के ग़लबे, दुश्मन के ग़लबे और दुश्मनों के ख़ुश होने से तेरी पनाह माँगता हूँ।", "क़र्ज़ के बोझ और दुश्मनों के ग़लबे से हिफ़ाज़त।", "नबी ﷺ इन चीज़ों से पनाह माँगा करते थे।"),
        "dua_faqr_qillah_dhillah" to DuaText("फ़क़्र और ज़िल्लत से पनाह", "ऐ अल्लाह! मैं फ़क़्र, कमी और ज़िल्लत से तेरी पनाह माँगता हूँ, और इस बात से कि मैं ज़ुल्म करूँ या मुझ पर ज़ुल्म किया जाए।", "तंगदस्ती, कमी और ज़िल्लत से बचने के लिए।", "नबी ﷺ की सिखाई हुई पनाह।"),
        "dua_five_things_new_muslim" to DuaText("बख़्श दे, रहम कर, हिदायत दे, आफ़ियत दे, रिज़्क़ दे", "ऐ अल्लाह! मुझे बख़्श दे, मुझ पर रहम फ़रमा, मुझे हिदायत दे, मुझे आफ़ियत दे और मुझे रिज़्क़ दे।", "नबी ﷺ नए मुसलमान को नमाज़ के साथ यह दुआ सिखाते।", "नबी ﷺ ने फ़रमाया: यह कलिमात तुम्हारे लिए दुनिया और आख़िरत जमा कर देते हैं।"),
        "dua_ruku_laka_raka_tu" to DuaText("रुकू में — तेरे लिए मैंने रुकू किया", "ऐ अल्लाह! मैंने तेरे लिए रुकू किया, तुझ पर ईमान लाया और तेरा फ़रमाँबरदार हुआ। मेरे कान, आँखें, दिमाग़, हड्डियाँ और पट्ठे तेरे आगे झुक गए।", "रुकू में (ख़ास तौर पर नफ़्ल नमाज़ में)।", "नबी ﷺ रुकू में यह पढ़ते।"),
        "dua_sujood_laka_sajadtu" to DuaText("सज्दे में — तुझे मैंने सज्दा किया", "ऐ अल्लाह! मैंने तुझे सज्दा किया, तुझ पर ईमान लाया और तेरा फ़रमाँबरदार हुआ। मेरा चेहरा उस ज़ात के आगे सज्दे में है जिसने उसे बनाया, उसकी सूरत बनाई और उसके कान और आँखें खोलीं। बरकत वाला है अल्लाह, सबसे बेहतर बनाने वाला।", "सज्दे में (ख़ास तौर पर नफ़्ल नमाज़ में)।", "नबी ﷺ सज्दे में यह पढ़ते।"),
        "dua_ruku_sujood_subhanaka" to DuaText("ऐ हमारे रब, तू पाक है — मुझे बख़्श दे", "ऐ अल्लाह, हमारे रब! तू पाक है अपनी तारीफ़ के साथ। ऐ अल्लाह! मुझे बख़्श दे।", "रुकू और सज्दे में।", "हज़रत आइशा (रज़ि.): नबी ﷺ रुकू और सुजूद में कसरत से यह पढ़ते।"),
        "dua_q_musa_li_akhi" to DuaText("मुझे और मेरे भाई को बख़्श दे (मूसा अ.)", "ऐ मेरे रब! मुझे और मेरे भाई को बख़्श दे और हमें अपनी रहमत में दाख़िल फ़रमा, और तू सब रहम करने वालों से बढ़कर रहम करने वाला है।", "अपने और अपने भाई/अज़ीज़ों के लिए मग़फ़िरत।", "हज़रत मूसा (अ.) की हारून (अ.) के लिए दुआ।"),
        "dua_q_ufawwidu_amri" to DuaText("मैं अपना मामला अल्लाह के सुपुर्द करता हूँ", "और मैं अपना मामला अल्लाह के सुपुर्द करता हूँ, बेशक अल्लाह बंदों को ख़ूब देखने वाला है।", "जब लोग मुख़ालिफ़त करें और मामला अल्लाह के सुपुर्द करना हो।", "आल-ए-फ़िरऔन के मोमिन का क़ौल; इसके बाद अल्लाह ने उसे उनकी बुरी चालों से बचा लिया।"),
        "dua_q_hawariyyun" to DuaText("हवारियों की दुआ — हमें गवाहों में लिख", "ऐ हमारे रब! जो तूने उतारा हम उस पर ईमान लाए और हमने रसूल की पैरवी की, तो हमें गवाही देने वालों में लिख ले।", "ईमान और रसूल की पैरवी पर साबित-क़दमी के लिए।", "हज़रत ईसा (अ.) के हवारियों की दुआ।"),
        "dua_q_la_tukhzini" to DuaText("मुझे रुसवा न कर (इब्राहीम अ.)", "और मुझे उस दिन रुसवा न करना जिस दिन लोग उठाए जाएँगे।", "क़यामत की रुसवाई से बचने के लिए।", "हज़रत इब्राहीम (अ.) की आख़िरत के लिए दुआ।"),
        "dua_iftar_laka_sumtu" to DuaText("इफ़्तार — तेरे लिए रोज़ा रखा", "ऐ अल्लाह! मैंने तेरे लिए रोज़ा रखा और तेरे ही रिज़्क़ से इफ़्तार किया।", "रोज़ा खोलते वक़्त (इफ़्तार की मशहूर दुआ)।", "नबी ﷺ इफ़्तार के वक़्त यह फ़रमाते। यह मुरसल रिवायत है जिसे दूसरी रिवायतों से तक़वियत मिलती है; अहनाफ़ और जमहूर के यहाँ इफ़्तार पर इसका पढ़ना मामूल है।"),
        "dua_iftar_ibn_umar" to DuaText("इफ़्तार — अपनी वसीअ रहमत से मुझे बख़्श दे", "ऐ अल्लाह! मैं तेरी उस रहमत के वसीले से जो हर चीज़ पर छाई हुई है, तुझसे सवाल करता हूँ कि मुझे बख़्श दे।", "इफ़्तार के वक़्त — हज़रत अब्दुल्लाह बिन अम्र (रज़ि.) यह दुआ करते; रोज़ेदार की दुआ इफ़्तार पर रद्द नहीं होती।", "हदीस: इफ़्तार के वक़्त रोज़ेदार की दुआ रद्द नहीं की जाती।"),
        "dua_inni_saim" to DuaText("रोज़े में कोई उकसाए तो", "मैं रोज़े से हूँ, मैं रोज़े से हूँ।", "रोज़े की हालत में कोई गाली दे या झगड़ा करे।", "नबी ﷺ ने फ़रमाया: रोज़ा ढाल है, तो रोज़ेदार न बेहूदा बात करे न जहालत — कोई झगड़े तो दो बार यह कहे।"),
        "dua_eid_takbeer" to DuaText("ईदगाह जाते वक़्त तकबीर", "अल्लाह सबसे बड़ा है, अल्लाह सबसे बड़ा है, अल्लाह के सिवा कोई माबूद नहीं, और अल्लाह सबसे बड़ा है, अल्लाह सबसे बड़ा है, और तमाम तारीफ़ अल्लाह ही के लिए है।", "चाँद रात से ईदुल फ़ित्र की नमाज़ तक, ख़ास तौर पर ईदगाह जाते हुए।", "क़ुरआन का हुक्म: 'ताकि तुम गिनती पूरी करो और अल्लाह की बड़ाई बयान करो' (अल-बक़रह 2:185)। हज़रत इब्न मसऊद (रज़ि.) यही तकबीर कहते।"),
        "dua_ahsin_aqibatana" to DuaText("हर काम में हमारा अंजाम अच्छा कर", "ऐ अल्लाह! तमाम कामों में हमारा अंजाम अच्छा फ़रमा, और हमें दुनिया की रुसवाई और आख़िरत के अज़ाब से बचा ले।", "हर काम के अच्छे अंजाम के लिए।", "जो यह दुआ करे वह आज़माइश से पहले वफ़ात पा जाए तो (फ़ितने से महफ़ूज़) मरा।"),
        "dua_fadlika_wa_rahmatik" to DuaText("तेरे फ़ज़्ल और रहमत का सवाल", "ऐ अल्लाह! मैं तुझसे तेरा फ़ज़्ल और तेरी रहमत माँगता हूँ, क्योंकि इनका मालिक तेरे सिवा कोई नहीं।", "रिज़्क़ और रहमत तलब करते वक़्त।", "नबी ﷺ के पास मेहमान आए और खाना न था तो आपने यह दुआ की, फिर हदिया आ गया।"),
        "dua_allahu_akbar_kabira_2696" to DuaText("देहाती को सिखाए गए कलिमात", "अल्लाह के सिवा कोई माबूद नहीं, वह अकेला है, उसका कोई शरीक नहीं। अल्लाह सबसे बहुत बड़ा है, और अल्लाह की बहुत ज़्यादा तारीफ़ है, पाक है अल्लाह जो तमाम जहानों का रब है, और गुनाह से बचने और नेकी करने की ताक़त सिर्फ़ अल्लाह ग़ालिब, हिकमत वाले की तरफ़ से है।", "ज़िक्र और दुआ का जामे कलिमा — एक देहाती को सिखाया गया।", "इसके बाद 'अल्लाहुम्मग़फ़िर ली वरहमनी वहदिनी वरज़ुक़नी' कहने की तलक़ीन फ़रमाई।"),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("अगले-पिछले गुनाह बख़्श दे", "ऐ अल्लाह! मेरे वह गुनाह बख़्श दे जो मैंने पहले किए और जो बाद में किए, जो छुपकर किए और जो खुलेआम किए, जो ज़्यादती की, और जिन्हें तू मुझसे ज़्यादा जानता है। तू ही आगे करने वाला और तू ही पीछे करने वाला है, तेरे सिवा कोई माबूद नहीं।", "तशह्हुद और दुरूद के बाद सलाम से पहले।", "नबी ﷺ नमाज़ के आख़िर में तशह्हुद और सलाम के दरमियान यह पढ़ते।"),
        "dua_jiddi_wa_hazli" to DuaText("संजीदगी और मज़ाक़ के गुनाह बख़्श दे", "ऐ अल्लाह! मेरे वह गुनाह बख़्श दे जो संजीदगी में हुए और जो मज़ाक़ में, जो ग़लती से हुए और जो जान-बूझकर, और यह सब मुझमें हैं।", "जाने-अनजाने हर तरह के गुनाहों की माफ़ी।", "नबी ﷺ का जामे इस्तिग़फ़ार।"),
        "dua_rising_ruku_mil" to DuaText("रुकू के बाद — आसमान भर तारीफ़", "ऐ हमारे रब! तेरे ही लिए तमाम तारीफ़ है, आसमानों भर, ज़मीन भर, और उसके बाद जो चीज़ तू चाहे उस भर।", "रुकू से उठकर 'रब्बना लकल-हम्द' के साथ।", "नबी ﷺ रुकू से उठकर यह फ़रमाते।"),
        "dua_istiftah_kabira" to DuaText("अल्लाह सबसे बड़ा, बहुत ज़्यादा तारीफ़", "अल्लाह सबसे बहुत बड़ा है, अल्लाह की बहुत ज़्यादा तारीफ़ है, और सुबह-शाम अल्लाह की पाकी है।", "नमाज़ शुरू करते वक़्त (सना की एक सूरत)।", "नबी ﷺ ने फ़रमाया: इसके लिए आसमान के दरवाज़े खोल दिए गए।"),
        "dua_q_ashku_bathhi" to DuaText("मैं सिर्फ़ अल्लाह से शिकायत करता हूँ (याक़ूब अ.)", "मैं अपनी परेशानी और ग़म की शिकायत सिर्फ़ अल्लाह से करता हूँ।", "गहरे ग़म और जुदाई के वक़्त।", "हज़रत याक़ूब (अ.) ने यूसुफ़ (अ.) की जुदाई में यह कहा।"),
        "dua_q_khayrun_hafiza" to DuaText("अल्लाह बेहतरीन हिफ़ाज़त करने वाला है", "तो अल्लाह ही बेहतरीन हिफ़ाज़त करने वाला है, और वह सब रहम करने वालों से बढ़कर रहम करने वाला है।", "बच्चों या अज़ीज़ों को सफ़र पर भेजते वक़्त।", "हज़रत याक़ूब (अ.) ने अपने बेटे को अल्लाह के सुपुर्द करते हुए कहा।"),
        "dua_q_aqraba_rashada" to DuaText("मेरा रब मुझे भलाई के क़रीब रास्ता दिखाए", "उम्मीद है कि मेरा रब मुझे इससे भी ज़्यादा भलाई के क़रीब रास्ता दिखा दे।", "किसी काम में बेहतर राह की तलाश हो।", "नबी ﷺ को भूल जाने पर यह कहने की तलक़ीन हुई।"),
        "dua_q_sawa_as_sabil" to DuaText("मुझे सीधा रास्ता दिखा (मूसा अ.)", "उम्मीद है कि मेरा रब मुझे सीधा रास्ता दिखाएगा।", "नए सफ़र या अनजान रास्ते पर चलते वक़्त।", "हज़रत मूसा (अ.) ने मदयन की तरफ़ रुख़ करते हुए कहा।"),
        "dua_q_not_among_wrongdoers" to DuaText("मुझे ज़ालिमों में शामिल न कर", "ऐ मेरे रब! मुझे ज़ालिम लोगों में शामिल न कर।", "अल्लाह से ज़ुल्म करने वालों से अलग रखने की दुआ।"),
        "dua_q_do_not_make_us_trial" to DuaText("हमें आज़माइश न बना", "ऐ हमारे रब! हमें काफ़िरों के लिए आज़माइश न बना और हमें बख़्श दे, ऐ हमारे रब! बेशक तू ही ग़ालिब, हिकमत वाला है।", "हज़रत इब्राहीम (अ.) और उनके साथियों की दुआ।"),
        "dua_morning_witness" to DuaText("सुबह तौहीद की गवाही", "ऐ अल्लाह! मैंने सुबह की, मैं तुझे, तेरे अर्श उठाने वालों, तेरे फ़रिश्तों और तेरी तमाम मख़लूक़ को गवाह बनाता हूँ कि तू ही अल्लाह है, तेरे सिवा कोई माबूद नहीं, तू अकेला है, तेरा कोई शरीक नहीं, और मुहम्मद ﷺ तेरे बंदे और रसूल हैं।", "रिवायत में सुबह चार बार पढ़ने का ज़िक्र आया है।"),
        "dua_evening_witness" to DuaText("शाम तौहीद की गवाही", "ऐ अल्लाह! मैंने शाम की, मैं तुझे, तेरे अर्श उठाने वालों, तेरे फ़रिश्तों और तेरी तमाम मख़लूक़ को गवाह बनाता हूँ कि तू ही अल्लाह है, तेरे सिवा कोई माबूद नहीं, तू अकेला है, तेरा कोई शरीक नहीं, और मुहम्मद ﷺ तेरे बंदे और रसूल हैं।", "रिवायत में शाम चार बार पढ़ने का ज़िक्र आया है।"),
        "dua_morning_blessing" to DuaText("सुबह नेमतों का शुक्र", "ऐ अल्लाह! सुबह के वक़्त मुझे या तेरी मख़लूक़ में से किसी को जो भी नेमत मिली, वह सिर्फ़ तेरी तरफ़ से है, तेरा कोई शरीक नहीं, तो तेरे ही लिए तारीफ़ है और तेरा ही शुक्र है।", "सुबह अल्लाह की नेमतों पर शुक्र का ज़िक्र।"),
        "dua_evening_blessing" to DuaText("शाम नेमतों का शुक्र", "ऐ अल्लाह! शाम के वक़्त मुझे या तेरी मख़लूक़ में से किसी को जो भी नेमत मिली, वह सिर्फ़ तेरी तरफ़ से है, तेरा कोई शरीक नहीं, तो तेरे ही लिए तारीफ़ है और तेरा ही शुक्र है।", "शाम अल्लाह की नेमतों पर शुक्र का ज़िक्र।"),
    )
}
